package br.com.brindespro.admin;
import br.com.brindespro.catalog.*;import br.com.brindespro.quote.*;import br.com.brindespro.security.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.time.*;import java.util.*;import java.util.stream.*;
@Service public class AdminService {private final ProductRepository products;private final CategoryRepository categories;private final QuoteRepository quotes;private final QuoteItemRepository quoteItems;private final CustomerRepository customers;private final AdminUserRepository users;private final AuditLogRepository logs;public AdminService(ProductRepository products,CategoryRepository categories,QuoteRepository quotes,QuoteItemRepository quoteItems,CustomerRepository customers,AdminUserRepository users,AuditLogRepository logs){this.products=products;this.categories=categories;this.quotes=quotes;this.quoteItems=quoteItems;this.customers=customers;this.users=users;this.logs=logs;}
 public record Dashboard(long quoteCount,BigDecimal estimatedValue,long customerCount,long productCount,List<Daily> dailyQuotes,List<Top> topProducts,List<Status> statusCounts){}public record Daily(String date,long count){}public record Top(String name,long count){}public record Status(String status,long count){}
 public Dashboard dashboard(){return summarize(quotes.findAll());}
 public Dashboard report(int days){if(days<1||days>366)throw new IllegalArgumentException("Período inválido.");LocalDate first=LocalDate.now().minusDays(days-1);return summarize(quotes.findAll().stream().filter(q->!q.createdAt.toLocalDate().isBefore(first)).toList());}
 private Dashboard summarize(List<Quote> all){BigDecimal value=all.stream().map(q->q.total).reduce(BigDecimal.ZERO,BigDecimal::add);Map<String,Long> daily=all.stream().collect(Collectors.groupingBy(q->q.createdAt.toLocalDate().toString(),TreeMap::new,Collectors.counting()));Map<String,Long> top=all.stream().flatMap(q->q.items.stream()).collect(Collectors.groupingBy(i->i.productName,Collectors.summingLong(i->i.quantity)));Map<String,Long> status=all.stream().collect(Collectors.groupingBy(q->q.status,Collectors.counting()));long customerCount=all.stream().map(q->q.customer.id).distinct().count();return new Dashboard(all.size(),value,customerCount,products.count(),daily.entrySet().stream().map(e->new Daily(e.getKey(),e.getValue())).toList(),top.entrySet().stream().sorted(Map.Entry.<String,Long>comparingByValue().reversed()).limit(10).map(e->new Top(e.getKey(),e.getValue())).toList(),status.entrySet().stream().map(e->new Status(e.getKey(),e.getValue())).toList());}
 public List<QuoteService.QuoteDto> quotes(String search,String status,String from,String to){return quotes.findAll().stream().filter(q->search.isBlank()||q.number.toLowerCase().contains(search.toLowerCase())||q.customer.name.toLowerCase().contains(search.toLowerCase())).filter(q->status.isBlank()||q.status.equals(status)).filter(q->from.isBlank()||!q.createdAt.toLocalDate().isBefore(LocalDate.parse(from))).filter(q->to.isBlank()||!q.createdAt.toLocalDate().isAfter(LocalDate.parse(to))).sorted(Comparator.comparing((Quote q)->q.createdAt).reversed()).map(QuoteService::dto).toList();}
 public record ProductInput(String name,String slug,String description,Long categoryId,String imageUrl,Boolean active,Integer minQuantity,BigDecimal initialPrice,List<VariantInput> variants,List<ImageInput> images,List<String> engravingOptions){}public record VariantInput(Long id,String color,String hex,String imageUrl,String material){}public record ImageInput(Long id,Long variantId,String imageUrl,String altText){}public record TierInput(Integer minQuantity,Integer maxQuantity,BigDecimal unitPrice){}
 @Transactional public CatalogController.ProductDto saveProduct(Long id,ProductInput input,String email){if(input.name()==null||input.name().isBlank()||input.slug()==null||!input.slug().matches("[a-z0-9-]+")||input.imageUrl()==null||input.imageUrl().isBlank()||input.variants()==null||input.variants().isEmpty())throw new IllegalArgumentException("Nome, slug, imagem e ao menos uma variação são obrigatórios.");if(id==null&&(input.initialPrice()==null||input.initialPrice().signum()<0||input.initialPrice().scale()>2))throw new IllegalArgumentException("Informe um preço inicial válido.");Product p=id==null?new Product(input.name(),input.slug(),categories.findById(input.categoryId()).orElseThrow(),input.imageUrl()):products.findById(id).orElseThrow();p.name=input.name();p.slug=input.slug();p.description=input.description()==null?"":input.description();p.category=categories.findById(input.categoryId()).orElseThrow();p.imageUrl=input.imageUrl();p.active=input.active()==null||input.active();p.minQuantity=input.minQuantity()==null?5:input.minQuantity();p.engravingOptions=input.engravingOptions()==null?"Laser":String.join(",",input.engravingOptions());Map<Long,ProductVariant> existing=new HashMap<>();for(ProductVariant variant:p.variants)existing.put(variant.id,variant);Set<Long> retained=new HashSet<>();for(VariantInput v:input.variants()){if(v.color()==null||v.color().isBlank()||v.material()==null||v.material().isBlank())throw new IllegalArgumentException("Cor e material são obrigatórios.");ProductVariant variant=v.id()==null?new ProductVariant(p,v.color(),v.hex(),v.imageUrl()==null||v.imageUrl().isBlank()?p.imageUrl:v.imageUrl(),v.material()):existing.get(v.id());if(variant==null)throw new IllegalArgumentException("Variação inválida.");variant.color=v.color();variant.hex=v.hex();variant.imageUrl=v.imageUrl()==null||v.imageUrl().isBlank()?p.imageUrl:v.imageUrl();variant.material=v.material();if(v.id()==null)p.variants.add(variant);else retained.add(v.id());}for(ProductVariant variant:new ArrayList<>(p.variants)){if(variant.id!=null&&!retained.contains(variant.id)){if(quoteItems.existsByVariantId(variant.id))throw new IllegalArgumentException("Variação utilizada em orçamento; mantenha-a cadastrada.");p.variants.remove(variant);}}if(input.images()!=null){p.images.clear();int order=0;for(ImageInput image:input.images()){if(image.imageUrl()==null||image.imageUrl().isBlank())throw new IllegalArgumentException("URL de imagem inválida.");p.images.add(new ProductImage(p,null,image.imageUrl(),image.altText()==null?p.name:image.altText(),order++));}}if(id==null)p.tiers.add(new PricingTier(p,p.minQuantity,null,input.initialPrice()));Product saved=products.saveAndFlush(p);audit(email,"Product",saved.id,id==null?"CREATE":"UPDATE",saved.name);return CatalogController.dto(saved);}
 @Transactional public List<CatalogController.TierDto> saveTiers(Long productId,List<TierInput> input,String email){Product p=products.findById(productId).orElseThrow();if(input.isEmpty())throw new IllegalArgumentException("Cadastre ao menos uma faixa.");List<TierInput> sorted=input.stream().sorted(Comparator.comparing(TierInput::minQuantity)).toList();int expected=p.minQuantity;for(int i=0;i<sorted.size();i++){TierInput t=sorted.get(i);if(t.minQuantity()==null||t.minQuantity()!=expected||t.unitPrice()==null||t.unitPrice().signum()<0||t.unitPrice().scale()>2)throw new IllegalArgumentException("Faixas devem ser contínuas e ter preços válidos.");if(i==sorted.size()-1){if(t.maxQuantity()!=null)throw new IllegalArgumentException("A última faixa deve ser aberta.");}else{if(t.maxQuantity()==null||t.maxQuantity()<t.minQuantity())throw new IllegalArgumentException("Limite da faixa inválido.");expected=t.maxQuantity()+1;}}p.tiers.clear();products.flush();for(TierInput t:sorted)p.tiers.add(new PricingTier(p,t.minQuantity(),t.maxQuantity(),t.unitPrice()));products.saveAndFlush(p);audit(email,"Product",p.id,"PRICES","Faixas de preço atualizadas");return p.tiers.stream().map(t->new CatalogController.TierDto(t.id,t.minQuantity,t.maxQuantity,t.unitPrice)).toList();}
 @Transactional public QuoteService.QuoteDto updateQuote(Long id,String status,String note,String email){Set<String> statuses=Set.of("Registrado","Em análise","Respondido","Em negociação","Aprovado","Cancelado");if(!statuses.contains(status))throw new IllegalArgumentException("Status inválido.");Quote q=quotes.findById(id).orElseThrow();q.status=status;q.internalNote=note==null?"":note;q.updatedAt=OffsetDateTime.now();audit(email,"Quote",q.id,"STATUS",status+(note==null?"":" - "+note));return QuoteService.dto(quotes.save(q));}
 public List<AuditLog> history(Long id){return logs.findByEntityTypeAndEntityIdOrderByCreatedAtDesc("Quote",id);}
 private void audit(String email,String type,Long id,String action,String details){Long userId=users.findByEmail(email).map(u->u.id).orElse(null);logs.save(new AuditLog(userId,type,id,action,details));}
}

